public static int readUShortBE(InputStream stream) throws IOException, BufferUnderrunException {
    int ch1 = stream.read();
    int ch2 = stream.read();
    if ((ch1 | ch2) < 0) {
        throw new BufferUnderrunException();
    }
    return (ch1 << 8) + (ch2);
}
